package nir.com.neonvegasslots;
import static org.junit.Assert.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34) public class WelcomeMomentTest{
 @Test public void momentNeverMintsCurrency(){SlotsView v=new SlotsView(RuntimeEnvironment.getApplication());long b=v.getBalance();String state=v.serialize();v.welcomeGiftMoment();v.welcomeGiftMoment();assertEquals(b,v.getBalance());assertEquals(state,v.serialize());}
 @GraphicsMode(GraphicsMode.Mode.NATIVE) @Test public void welcomeFrame()throws Exception{SlotsView v=new SlotsView(RuntimeEnvironment.getApplication());v.layout(0,0,640,1040);v.welcomeGiftMoment();android.graphics.Bitmap b=android.graphics.Bitmap.createBitmap(640,1040,android.graphics.Bitmap.Config.ARGB_8888);v.draw(new android.graphics.Canvas(b));try(java.io.FileOutputStream f=new java.io.FileOutputStream("/tmp/renders/neonvegasslots-welcome.png")){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,f);}}
 @Test public void freshLaunchMarksWelcomeAndDoesNotAddCoinsOnRestart()throws Exception{android.content.SharedPreferences sp=RuntimeEnvironment.getApplication().getSharedPreferences(MainActivity.PREFS,0);sp.edit().clear().commit();Splash.enabled=false;Reminders.promptEnabled=false;org.robolectric.android.controller.ActivityController<MainActivity> c=Robolectric.buildActivity(MainActivity.class).setup();MainActivity a=c.get();assertTrue(sp.getBoolean("welcome_shown",false));java.lang.reflect.Field f=MainActivity.class.getDeclaredField("game");f.setAccessible(true);SlotsView v=(SlotsView)f.get(a);assertEquals(500,v.getBalance());a.saveState();c.pause().stop().destroy();org.robolectric.android.controller.ActivityController<MainActivity> d=Robolectric.buildActivity(MainActivity.class).setup();assertEquals(500,((SlotsView)f.get(d.get())).getBalance());d.pause().stop().destroy();}
 @GraphicsMode(GraphicsMode.Mode.NATIVE) @Config(sdk=34,qualifiers="w320dp-h570dp-hdpi") @Test public void narrowLargeFontWelcomeKeepsStateAndFitsText()throws Exception{android.content.Context c=RuntimeEnvironment.getApplication();android.util.DisplayMetrics dm=c.getResources().getDisplayMetrics();float old=dm.scaledDensity;try{dm.scaledDensity=dm.density*1.35f;SlotsView v=new SlotsView(c);v.layout(0,0,420,v.minimumContentHeight(420));String state=v.serialize();v.welcomeGiftMoment();android.graphics.Bitmap b=android.graphics.Bitmap.createBitmap(420,v.getHeight(),android.graphics.Bitmap.Config.ARGB_8888);v.draw(new android.graphics.Canvas(b));String[] before=state.split(";",-1),after=v.serialize().split(";",-1);for(int i=0;i<before.length;i++)if(i!=3)assertEquals(before[i],after[i]);try(java.io.FileOutputStream f=new java.io.FileOutputStream("/tmp/renders/neonvegasslots-welcome-narrow135.png")){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,f);}}finally{dm.scaledDensity=old;}}

}
